package com.iniyo.store.controller;
import com.iniyo.store.model.*; import com.iniyo.store.repo.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.math.*; import java.util.*;
@RestController @RequestMapping("/api/orders") public class OrderController {final UserRepo users;final ProductRepo products;final OrderRepo orders;public OrderController(UserRepo u,ProductRepo p,OrderRepo o){users=u;products=p;orders=o;} public record Item(Long productId,int quantity){} public record Req(List<Item> items,String paymentMethod){} @PostMapping public Order create(Authentication a,@RequestBody Req r){User u=users.findByEmail(a.getName()).orElseThrow();if(r.items()==null||r.items().isEmpty())throw new IllegalArgumentException("Cart is empty");Order o=new Order();o.user=u;o.paymentMethod=r.paymentMethod()==null?"COD":r.paymentMethod();BigDecimal total=BigDecimal.ZERO;for(Item i:r.items()){Product p=products.findById(i.productId()).orElseThrow();if(i.quantity()<1)throw new IllegalArgumentException("Invalid quantity");o.items.add(new OrderItem(p,i.quantity()));total=total.add(p.price.multiply(BigDecimal.valueOf(i.quantity())));}o.total=total;return orders.save(o);} @GetMapping public List<Order> mine(Authentication a){return orders.findByUserOrderByCreatedAtDesc(users.findByEmail(a.getName()).orElseThrow());}}
